<template>
<div><nav class="navbar"><RouterLink class="logo" to="/">EasyJob</RouterLink><AppNavigation /></nav><main class="security-layout"><h1>账号安全</h1><p>管理密码和登录设备。</p>
<section class="security-card"><h2>修改密码</h2><form @submit.prevent="changePassword"><label>当前密码<input v-model="current" type="password" autocomplete="current-password" required /></label><label>新密码<input v-model="password" type="password" autocomplete="new-password" minlength="8" required /></label><label>再次输入新密码<input v-model="repeat" type="password" autocomplete="new-password" required /></label><small>至少8个字符，不超过72字节。修改成功后所有设备需要重新登录。</small><button :disabled="busy">{{ busy?'正在处理…':'更新密码' }}</button></form><RouterLink to="/password-reset">忘记当前密码？通过邮箱找回 ↗</RouterLink></section>
<section class="security-card"><div class="security-heading"><h2>登录设备</h2><button :disabled="busy || loading" @click="load">刷新</button><button :disabled="busy || loading" @click="revokeOthers">退出其他设备</button></div><p v-if="loading">正在读取…</p><p v-if="loadError" role="alert">{{ loadError }}</p><p v-else-if="!loading && !devices.length">暂无设备记录。重新登录后会显示当前设备。</p><article v-for="device in devices" :key="device.id" class="device-row"><div><strong>{{ browser(device.userAgent) }} <span v-if="device.current">· 当前设备</span></strong><p>登录于 {{ time(device.createdAt) }} · 最近续签 {{ time(device.lastSeen) }}</p><details><summary>浏览器信息</summary><p>{{ device.userAgent }}</p></details></div><button :disabled="busy" @click="revoke(device)">退出</button></article></section><p role="status">{{ message }}</p></main></div>
</template>
<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import AppNavigation from '@/components/AppNavigation.vue';import request from '@/utils/request';import {signOutSession} from '@/utils/authSession';import {confirmAction} from '@/utils/feedback'
const router=useRouter(),devices=ref<any[]>([]),loading=ref(false),busy=ref(false),message=ref(''),loadError=ref(''),current=ref(''),password=ref(''),repeat=ref('')
const time=(v:number)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'未知'
function browser(ua:string){return /Edg\//.test(ua)?'Microsoft Edge':/Chrome\//.test(ua)?'Chrome':/Firefox\//.test(ua)?'Firefox':/Safari\//.test(ua)?'Safari':ua||'未知浏览器'}
async function load(){loading.value=true;loadError.value='';try{const r:any=await request.get('/account/sessions');devices.value=r.data}catch(e){loadError.value=e instanceof Error?e.message:'读取失败'}finally{loading.value=false}}
async function logout(){try{await signOutSession()}finally{await router.replace({path:'/',query:{login:'true'}})}}
async function action(work:()=>Promise<unknown>){if(busy.value)return;busy.value=true;message.value='';try{await work()}catch(e){message.value=e instanceof Error?e.message:'操作失败，请重试'}finally{busy.value=false}}
async function revoke(device:any){if(!await confirmAction(device.current?'退出当前设备？':'退出这台设备？','退出设备'))return;await action(async()=>{await request.delete(`/account/sessions/${device.id}`);if(device.current)await logout();else{message.value='该设备已退出';await load()}})}
async function revokeOthers(){if(!await confirmAction('让其他登录设备退出？当前设备继续使用。','退出其他设备'))return;await action(async()=>{await request.post('/account/sessions/revoke-others');message.value='其他设备已退出';await load()})}
async function changePassword(){if(password.value!==repeat.value){message.value='两次新密码不一致';return}if(new TextEncoder().encode(password.value).length>72){message.value='密码不能超过72字节';return}await action(async()=>{await request.put('/account/password',{currentPassword:current.value,newPassword:password.value});current.value=password.value=repeat.value='';await logout()})}
onMounted(load)
</script>
<style scoped>
.navbar{height:76px;padding:0 4%;display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--ej-line);background:var(--ej-canvas)}.logo{color:var(--ej-ink);font-size:24px;font-weight:850;text-decoration:none;display:inline-flex;align-items:center;gap:10px}.security-card a{color:var(--ej-ink);text-decoration:none}.security-card a:hover{text-decoration:underline}@media(max-width:600px){.navbar{padding:0 16px}}
.security-layout{max-width:900px;margin:44px auto;padding:0 24px}.security-layout h1{font-size:28px}.security-layout>p,small{color:var(--ej-muted)}.security-card{padding:28px;margin:24px 0;border:1px solid var(--ej-line);border-radius:24px;background:var(--ej-surface)}h2{font-size:20px;margin:0 0 18px}.security-card form{display:grid;gap:14px;max-width:460px;margin-bottom:18px}.security-card label{display:grid;gap:8px}.security-card input{padding:12px;border:1px solid var(--ej-line);border-radius:12px;background:var(--ej-bg)}button{border:1px solid var(--ej-line);border-radius:99px;padding:9px 16px;background:var(--ej-surface);cursor:pointer}form button{background:var(--studio-lime)}button:disabled{opacity:.5}.security-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.security-heading h2{margin-right:auto}.device-row{border-top:1px solid var(--ej-line);padding:20px 0;display:flex;gap:20px;align-items:center}.device-row>div{flex:1;min-width:0}.device-row p{font-size:13px;color:var(--ej-muted);overflow-wrap:anywhere}.device-row summary{font-size:12px;cursor:pointer}
</style>
